// Classify user intent with a tiny Groq call
// This node fires after BOTH schema and history are ready
// We just pass through — the next Groq node does classification inline

const schema      = $('MCP: get_schema_overview').item.json;
const history     = $('Supabase: Fetch History').all().map(i => i.json);
const userMessage = $('chat').item.json.body.user_message;
const sessionId   = $('chat').item.json.body.session_id;

// Reverse history so oldest message is first
const historyMessages = history
  .reverse()
  .map(msg => ({ role: msg.role, content: msg.content }));

return [{
  json: {
    session_id:       sessionId,
    user_message:     userMessage,
    schema:           schema,
    history_messages: historyMessages
  }
}];

