const intentRaw = $input.first().json.choices[0].message.content.trim().toUpperCase();
const valid = ['UNDERSTAND', 'COMPARE', 'BREAKDOWN', 'QUERY', 'OTHER'];
const intent = valid.includes(intentRaw) ? intentRaw : 'OTHER';

const intentPrompts = {
  UNDERSTAND: 'Explain WHY this metric changed or what drives it. Use plain everyday language. Quantify contributing factors where possible.',
  COMPARE:    'Generate a clear comparison. Identify which differences are meaningful vs noise. Include a comparison table in your JSON response.',
  BREAKDOWN:  'Decompose this number step by step. Show the components. Include both narrative and structured data for a chart.',
  QUERY:      'Retrieve the exact data requested. Generate a SELECT query, run it, and present results clearly.',
  OTHER:      'Answer helpfully using the available schema and data context.'
};

const ctx = $('Merge Context').item.json;

return [{
  json: {
    intent:           intent,
    intent_prompt:    intentPrompts[intent],
    session_id:       ctx.session_id,
    user_message:     ctx.user_message,
    schema:           ctx.schema,
    history_messages: ctx.history_messages
  }
}];

