const raw = $input.first().json.choices[0].message.content.trim();
const ctx = $('Route Intent').item.json;

let parsed;
try {
  const cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    response_text: raw,
    chart_data:    null,
    query_to_run:  null,
    sources:       []
  };
}

return [{
  json: {
    session_id:       ctx.session_id,
    user_message:     ctx.user_message,
    intent:           ctx.intent,
    response_text:    parsed.response_text  || '',
    chart_data:       parsed.chart_data     || null,
    query_to_run:     parsed.query_to_run   || null,
    sources:          parsed.sources        || []
  }
}];

// Merge query results back into the response if a query was run
const parseNode = $('Parse Chat Response').item.json;

let queryResults = null;
try {
  const queryNode = $('MCP: run_analysis_query').item;
  if (queryNode) queryResults = queryNode.json;
} catch(e) {
  // No query was run — IF took the false branch
}

return [{
  json: {
    session_id:    parseNode.session_id,
    user_message:  parseNode.user_message,
    intent:        parseNode.intent,
    response_text: parseNode.response_text,
    chart_data:    parseNode.chart_data,
    sources:       parseNode.sources,
    query_results: queryResults
  }
}];
